(window.__ixData=window.__ixData||[]).push(function(D){D["est2-about"]=[{t:"qc",ti:"Quick Check: EST II Subject Test Format",ti_ar:"فحص سريع: هيكل اختبار EST II التخصصي",q:"What are the question count and timing specifications for the EST II Math Subject Exam?",q_ar:"ما هو عدد الأسئلة والمواصفات الزمنية لاختبار EST II التخصصي في الرياضيات؟",o:["50 multiple-choice questions in 60 minutes","60 questions in 90 minutes","40 questions in 45 minutes","30 questions in 60 minutes"],o_ar:["50 سؤال اختيار من متعدد في 60 دقيقة","60 سؤالاً في 90 دقيقة","40 سؤالاً في 45 دقيقة","30 سؤالاً في 60 دقيقة"],a:0,ex:"The EST II Math Subject Test consists of 50 multiple-choice questions in 60 minutes (average of 72 seconds per question), covering advanced algebra, geometry, trigonometry, functions, and introductory precalculus.",ex_ar:"يتكون اختبار EST II في الرياضيات من 50 سؤال اختيار من متعدد في 60 دقيقة (بمتوسط 72 ثانية لكل سؤال)، ويغطي الجبر المتقدم والهندسة وحساب المثلثات والدوال ومقدمة ما قبل التفاضل والتكامل."},{t:"num",ti:"Numeric Entry: EST II Target Pace",ti_ar:"إدخال رقمي: وتيرة الوقت المستهدفة في EST II",q:"On the EST II Math test, you have 60 minutes for 50 questions. How many seconds do you have per question on average?",q_ar:"في اختبار EST II للرياضيات، لديك 60 دقيقة لحل 50 سؤالاً. كم ثانية تتاح لك لكل سؤال في المتوسط؟",a:72,ex:"(60 minutes × 60 seconds/minute) ÷ 50 questions = 3600 ÷ 50 = 72 seconds per question.",ex_ar:"(60 دقيقة × 60 ثانية/دقيقة) ÷ 50 سؤالاً = 3600 ÷ 50 = 72 ثانية لكل سؤال."},{t:"mt",ti:"Matching: EST II Key Strategy Rules",ti_ar:"مطابقة: قواعد الاستراتيجية الأساسية لاختبار EST II",p:[{l:"Time Management",l_ar:"إدارة الوقت",r:"72 seconds per question average",r_ar:"متوسط 72 ثانية لكل سؤال"},{l:"Calculator Use",l_ar:"استخدام الحاسبة",r:"Permitted throughout the 60-minute test",r_ar:"مسموح بها طوال مدة الاختبار (60 دقيقة)"},{l:"Trig & Coordinates",l_ar:"المثلثات والإحداثيات",r:"High focus on unit circle, conic sections, and vectors",r_ar:"تركيز عالٍ على دائرة الوحدة والقطوع المخروطية والمتجهات"},{l:"Negative Marking",l_ar:"عقوبة التخمين",r:"Zero penalty — answer every question",r_ar:"لا توجد عقوبة — أجب عن جميع الأسئلة دون ترك فراغات"}]},{t:"ord",ti:"Order the Steps: Three-Pass Strategy for EST II Math",ti_ar:"رتّب الخطوات: استراتيجية الجولات الثلاث لاختبار EST II Math",prompt:"Arrange the recommended sequence to tackle the 50-question EST II Math exam:",prompt_ar:"رتب التسلسل الموصى به للتعامل مع أسئلة اختبار EST II Math الخمسين:",items:["Pass 1 (Questions 1–25, ~20 min): bank routine algebra, linear functions, and arithmetic fast.","Pass 2 (Questions 26–45, ~25 min): solve conic equations, solid geometry, and multi-step probability.","Pass 3 (Questions 46–50, ~12 min): tackle non-routine proofs, vectors, and complex number manipulations.","Final Review (~3 min): verify all flagged items and confirm zero answers are left blank."],items_ar:["الجولة 1 (الأسئلة 1–25، ~20 دقيقة): حصد درجات الجبر الروتيني والدوال الخطية والحسابيات بسرعة.","الجولة 2 (الأسئلة 26–45، ~25 دقيقة): حل معادلات القطوع والهندسة المجسمة والاحتمالات متعددة الخطوات.","الجولة 3 (الأسئلة 46–50، ~12 دقيقة): التعامل مع الإثباتات غير النمطية والمتجهات والأعداد المركبة.","المراجعة النهائية (~3 دقائق): تدقيق الأسئلة المؤشرة والتأكد من عدم ترك أي سؤال فارغاً."],ex:"A disciplined three-pass execution secures all accessible points early while leaving buffer time for harder discrimination items.",ex_ar:"التنفيذ المنضبط للجولات الثلاث يضمن حصد كافة النقاط السهلة مبكراً مع إتاحة وقت كافٍ للأسئلة المتقدمة."},{t:"cat",ti:"Categorize: EST II Domain Weightings",ti_ar:"تصنيف: الأوزان النسبية لمجالات اختبار EST II",categories:["High-Yield (15–20%)","Core Foundations (10%)","Specialized (5%)"],categories_ar:["أعلى تركيزاً (15–20%)","أساسيات محورية (10%)","تخصصية (5%)"],items:[{s:"Advanced Algebra (polynomials, logs, rationals)",s_ar:"الجبر المتقدم (كثيرات الحدود، اللوغاريتمات، الدوال النسبية)",cat:0},{s:"Functions & Transformations",s_ar:"الدوال والتحويلات الهندسية",cat:0},{s:"Trigonometry & Unit Circle",s_ar:"حساب المثلثات ودائرة الوحدة",cat:0},{s:"Sequences, Series & Complex Numbers",s_ar:"المتتابعات والمتسلسلات والأعداد المركبة",cat:1},{s:"Circles & Coordinate Geometry",s_ar:"الدوائر والهندسة الإحداثية",cat:1},{s:"Statistics & Probability",s_ar:"الإحصاء والاحتمالات",cat:1},{s:"Geometry (Lines, Triangles & Polygons)",s_ar:"الهندسة المستوية (المستقيمات والمثلثات والمضلعات)",cat:1},{s:"Solid Geometry & 3D Similarity",s_ar:"الهندسة الفراغية وتناسب المجسمات ثلاثية الأبعاد",cat:2}],ex:"Advanced Algebra, Functions, and Trigonometry account for 55% of the total test weight.",ex_ar:"يمثل الجبر المتقدم والدوال وحساب المثلثات نحو 55% من إجمالي وزن الاختبار."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Test format & strategy)",q:"A student solves the equation \\(\\sqrt{2x + 25} = x - 5\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 25 = (x - 5)^2\\).","Expand the right-hand side: \\(2x + 25 = x^2 - 10x + 25\\).","Rearrange and factor: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 12\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{25} = -5\\) (\\(5 = -5\\)), which is false because the principal square root is non-negative (\\(x - 5 \\ge 0\\) requires \\(x \\ge 5\\)).","Expanding \\((x - 5)^2\\) should give \\(x^2 - 25\\) with no middle term.","Factoring \\(x^2 - 12x = 0\\) only yields \\(x = 12\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 25} = x - 5\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 5 \\ge 0 \\iff x \\ge 5\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 12\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Test format & strategy)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 25} = x - 5\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 25 = (x - 5)^2\\).","فك المربع الكامل: \\(2x + 25 = x^2 - 10x + 25\\).","الترتيب والتحليل: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 12\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(5 = -5\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 5\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 5 \\ge 0 \\implies x \\ge 5\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 12\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Test format & strategy)",q:"Let \\(f(x) = x^2 - 10x + 27\\) for \\(x \\ge 5\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 5)^2 - 25 + 27 = (x - 5)^2 + 2\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 2\\) (or \\([2, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 5)^2 + 2 \\implies (x - 5)^2 = y - 2\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 5\\)): \\(f^{-1}(x) = 5 + \\sqrt{x - 2}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 2\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 2}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 5\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Test format & strategy)",q_ar:"لتكن \\(f(x) = x^2 - 10x + 27\\) حيث \\(x \\ge 5\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(5 + \\sqrt{x - 2}\\) لأن \\(x \\ge 5\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Test format & strategy)",steps:[{l:"In \\(y = x^2 - 10x + 27\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"5",h:"Take half of 10."},{l:"Compute the minimum value \\(k = 27 - 5^2 =\\)",a:"2",h:"Subtract 25 from 27."},{l:"Evaluate \\(y\\) when \\(x = 7\\): \\(y =\\)",a:"6",h:"Compute \\((2)^2 + 2\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Test format & strategy)",steps_ar:[{l:"في الدالة \\(y = x^2 - 10x + 27\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"5",h:"اقسم معامل x وهو 10 على 2."},{l:"احسب القيمة الصغرى \\(k = 27 - 5^2 =\\)",a:"2",h:"اطرح 25 من 27."},{l:"احسب قيمة \\(y\\) عندما \\(x = 7\\):",a:"6",h:"احسب \\(4 + 2\\)."}]},{t:"qc",ti:"Quick Check: Vertex & Minimum Analysis (Test format & strategy)",ti_ar:"فحص سريع: تحليل نقطة الرأس والقيمة الصغرى (Test format & strategy)",q:"What is the minimum value of \\( f(x) = (x - 3)^2 + 5 \\) over all real \\( x \\)?",q_ar:"ما هي القيمة الصغرى للدالة \\( f(x) = (x - 3)^2 + 5 \\) لكل \\( x \\in \\mathbb{R} \\)؟",o:["\\( 5 \\)","\\( 3 \\)","\\( -3 \\)","\\( 14 \\)"],o_ar:["\\( 5 \\)","\\( 3 \\)","\\( -3 \\)","\\( 14 \\)"],a:0,ex:"Since \\( (x - 3)^2 \\ge 0 \\), the minimum value is \\( 5 \\) achieved at \\( x = 3 \\).",ex_ar:"بما أن المربع الكامل غير سالب، فإن القيمة الصغرى هي \\( 5 \\) عند \\( x = 3 \\)."}];D["est2-algebra"]=[{t:"qc",ti:"Quick Check: Simplifying",ti_ar:"فحص سريع: التبسيط",q:"Simplify \\(\\frac{2x^2+6x}{2x}\\), \\(x\\neq0\\)",q_ar:"بسط المقدار \\(\\frac{2x^2+6x}{2x}\\)، حيث \\(x\\neq0\\)",o:["x+3","x²+3","2x+3","x+6"],o_ar:["x+3","x²+3","2x+3","x+6"],a:0,ex:"\\(\\frac{2x(x+3)}{2x}=x+3\\).",ex_ar:"\\(\\frac{2x(x+3)}{2x}=x+3\\)."},{t:"num",ti:"Numeric Entry: Remainder Theorem",ti_ar:"إدخال رقمي: نظرية الباقي",q:"If \\(P(x) = 2x^3 - 5x^2 + 4x - 7\\), what is the remainder when \\(P(x)\\) is divided by \\(x - 2\\)?",q_ar:"إذا كانت \\(P(x) = 2x^3 - 5x^2 + 4x - 7\\)، فما هو باقي قسمة \\(P(x)\\) على \\(x - 2\\)؟",a:-3,ex:"By the Remainder Theorem, remainder is P(2) = 2(2)³ - 5(2)² + 4(2) - 7 = 16 - 20 + 8 - 7 = -3.",ex_ar:"وفقاً لنظرية الباقي، الباقي هو P(2) = 2(2)³ - 5(2)² + 4(2) - 7 = 16 - 20 + 8 - 7 = -3."},{t:"ord",ti:"Order the Steps: Solving a Rational Equation",ti_ar:"رتّب الخطوات: حل معادلة كسرية نسبية",prompt:"Arrange the steps to solve \\(\\dfrac{x}{x-2} + \\dfrac{1}{x+2} = \\dfrac{8}{x^2-4}\\):",prompt_ar:"رتب خطوات حل المعادلة الكسرية \\(\\dfrac{x}{x-2} + \\dfrac{1}{x+2} = \\dfrac{8}{x^2-4}\\):",items:["Factor all denominators: x² - 4 = (x - 2)(x + 2).","Multiply both sides by the LCD (x - 2)(x + 2) to eliminate fractions.","Expand and collect terms: x(x + 2) + (x - 2) = 8 ⇒ x² + 3x - 10 = 0.","Factor the quadratic equation: (x + 5)(x - 2) = 0.","Reject extraneous solution x = 2 (denominator zero) and conclude x = -5."],items_ar:["تحليل جميع المقامات إلى عوامل: x² - 4 = (x - 2)(x + 2).","ضرب كلا الطرفين في المضاعف المشترك الأصغر (x - 2)(x + 2) للتخلص من المقامات.","فك الأقواس وتجميع الحدود: x(x + 2) + (x - 2) = 8 ⇒ x² + 3x - 10 = 0.","تحليل المعادلة التربيعية: (x + 5)(x - 2) = 0.","استبعاد الحل الدخيل x = 2 (يجعل المقام صفراً) واعتماد الحل الوحيد الصحيح x = -5."],ex:"Clearing the LCD, solving the resulting quadratic, and filtering out extraneous roots gives the single valid solution x = -5.",ex_ar:"التخلص من المقامات، وحل المعادلة التربيعية الناتجة، واستبعاد الجذور الدخيلة يثبت أن الحل الصحيح الوحيد هو x = -5."},{t:"sr",ti:"Worked Example: Solve a Rational Equation",ti_ar:"مثال محلول: حل معادلة نسبية",steps:["Solve \\(\\dfrac3x+2=5\\). Isolate the fraction: \\(\\dfrac3x=3\\).","Multiply both sides by \\(x\\): \\(3=3x\\).","Solve: \\(x=1\\)."],steps_ar:["حل المعادلة \\(\\dfrac3x+2=5\\). اعزل الكسر: \\(\\dfrac3x=3\\).","اضرب كلا الطرفين في \\(x\\): \\(3=3x\\).","الحل: \\(x=1\\)."]},{t:"cat",ti:"Categorize: Polynomial Theorems & Solutions",ti_ar:"تصنيف: نظريات وحلول كثيرات الحدود",categories:["Factor Theorem","Remainder Theorem","Extraneous Root Condition"],categories_ar:["نظرية العوامل","نظرية الباقي","حالة الجذر الدخيل"],items:[{s:"If P(3) = 0, then (x - 3) divides P(x) with no remainder",s_ar:"إذا كان P(3) = 0، فإن (x - 3) يقسم P(x) دون باقٍ",cat:0},{s:"Dividing P(x) by (x + 4) yields a remainder equal to P(-4)",s_ar:"قسمة P(x) على (x + 4) تعطي باقياً يساوي P(-4)",cat:1},{s:"A candidate root makes an original denominator in a rational equation zero",s_ar:"قيمة مرشحة تجعل مقاماً أصلياً في المعادلة الكسرية مساوياً للصفر",cat:2},{s:"(x - c) is a factor of P(x) if and only if P(c) = 0",s_ar:"(x - c) عامل لـ P(x) إذا وفقط إذا كان P(c) = 0",cat:0},{s:"Evaluating P(2) determines the remainder of P(x) ÷ (x - 2)",s_ar:"حساب P(2) يحدد باقي قسمة P(x) ÷ (x - 2)",cat:1}],ex:"The Factor Theorem tests divisibility, the Remainder Theorem gives remainder P(c), and extraneous roots are disqualified when denominators vanish.",ex_ar:"تحدد نظرية العوامل قابلية القسمة، وتعطي نظرية الباقي قيمة الباقي P(c)، وتستبعد الحلول الدخيلة عند انعدام المقامات."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Advanced Algebra)",q:"A student solves the equation \\(\\sqrt{2x + 16} = x - 4\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 16 = (x - 4)^2\\).","Expand the right-hand side: \\(2x + 16 = x^2 - 8x + 16\\).","Rearrange and factor: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 10\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{16} = -4\\) (\\(4 = -4\\)), which is false because the principal square root is non-negative (\\(x - 4 \\ge 0\\) requires \\(x \\ge 4\\)).","Expanding \\((x - 4)^2\\) should give \\(x^2 - 16\\) with no middle term.","Factoring \\(x^2 - 10x = 0\\) only yields \\(x = 10\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 16} = x - 4\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 4 \\ge 0 \\iff x \\ge 4\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 10\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Advanced Algebra)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 16} = x - 4\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 16 = (x - 4)^2\\).","فك المربع الكامل: \\(2x + 16 = x^2 - 8x + 16\\).","الترتيب والتحليل: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 10\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(4 = -4\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 4\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 4 \\ge 0 \\implies x \\ge 4\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 10\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Advanced Algebra)",q:"Let \\(f(x) = x^2 - 8x + 20\\) for \\(x \\ge 4\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 4)^2 - 16 + 20 = (x - 4)^2 + 4\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 4\\) (or \\([4, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 4)^2 + 4 \\implies (x - 4)^2 = y - 4\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 4\\)): \\(f^{-1}(x) = 4 + \\sqrt{x - 4}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 4\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 4}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 4\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Advanced Algebra)",q_ar:"لتكن \\(f(x) = x^2 - 8x + 20\\) حيث \\(x \\ge 4\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(4 + \\sqrt{x - 4}\\) لأن \\(x \\ge 4\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Advanced Algebra)",steps:[{l:"In \\(y = x^2 - 8x + 20\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"4",h:"Take half of 8."},{l:"Compute the minimum value \\(k = 20 - 4^2 =\\)",a:"4",h:"Subtract 16 from 20."},{l:"Evaluate \\(y\\) when \\(x = 6\\): \\(y =\\)",a:"8",h:"Compute \\((2)^2 + 4\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Advanced Algebra)",steps_ar:[{l:"في الدالة \\(y = x^2 - 8x + 20\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"4",h:"اقسم معامل x وهو 8 على 2."},{l:"احسب القيمة الصغرى \\(k = 20 - 4^2 =\\)",a:"4",h:"اطرح 16 من 20."},{l:"احسب قيمة \\(y\\) عندما \\(x = 6\\):",a:"8",h:"احسب \\(4 + 4\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Advanced Algebra)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Advanced Algebra)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["est2-functions"]=[{t:"mt",ti:"Matching: Function Operations",ti_ar:"مطابقة: العمليات على الدوال",p:[{l:"(f+g)(x)",l_ar:"(f+g)(x)",r:"f(x)+g(x)",r_ar:"f(x)+g(x)"},{l:"(fg)(x)",l_ar:"(fg)(x)",r:"f(x)·g(x)",r_ar:"f(x)·g(x)"},{l:"(f∘g)(x)",l_ar:"(f∘g)(x)",r:"f(g(x))",r_ar:"f(g(x))"},{l:"Range of f⁻¹",l_ar:"مدى f⁻¹",r:"Domain of f",r_ar:"مجال f"}]},{t:"num",ti:"Numeric Entry: Value of Inverse Function",ti_ar:"إدخال رقمي: قيمة الدالة العكسية",q:"If \\(f(x) = \\dfrac{3x - 5}{2}\\), evaluate \\(f^{-1}(8)\\).",q_ar:"إذا كانت \\(f(x) = \\dfrac{3x - 5}{2}\\)، فاحسب قيمة \\(f^{-1}(8)\\).",a:7,ex:"Setting f(x) = 8: (3x - 5)/2 = 8 ⇒ 3x - 5 = 16 ⇒ 3x = 21 ⇒ x = 7. Thus f⁻¹(8) = 7.",ex_ar:"بمساواة f(x) = 8: (3x - 5)/2 = 8 ⇒ 3x - 5 = 16 ⇒ 3x = 21 ⇒ x = 7. إذن f⁻¹(8) = 7."},{t:"cat",ti:"Categorize: Function Symmetry",ti_ar:"تصنيف: تماثل الدوال",categories:["Even Function","Odd Function","Neither"],categories_ar:["دالة زوجية","دالة فردية","ليست زوجية ولا فردية"],items:[{s:"f(x) = x⁴ - 3x² + 5",s_ar:"f(x) = x⁴ - 3x² + 5",cat:0},{s:"f(x) = \\cos(x)",s_ar:"f(x) = \\cos(x)",cat:0},{s:"f(x) = x³ - 4x",s_ar:"f(x) = x³ - 4x",cat:1},{s:"f(x) = \\sin(x)",s_ar:"f(x) = \\sin(x)",cat:1},{s:"f(x) = x³ + x²",s_ar:"f(x) = x³ + x²",cat:2},{s:"f(x) = e^x",s_ar:"f(x) = e^x",cat:2}],ex:"Even functions satisfy f(-x) = f(x) (reflection across y-axis). Odd functions satisfy f(-x) = -f(x) (180° rotational symmetry about origin).",ex_ar:"الدوال الزوجية تحقق f(-x) = f(x) (تماثل انعكاسي حول محور y). والدوال الفردية تحقق f(-x) = -f(x) (تماثل دوراني بزاوية 180° حول نقطة الأصل)."},{t:"ord",ti:"Order the Steps: Finding an Inverse Function",ti_ar:"رتّب الخطوات: إيجاد قاعدة الدالة العكسية",prompt:"Arrange the steps to find the inverse of \\(f(x) = \\dfrac{2x + 1}{x - 3}\\):",prompt_ar:"رتب خطوات إيجاد الدالة العكسية للدالة \\(f(x) = \\dfrac{2x + 1}{x - 3}\\):",items:["Replace f(x) with y: y = (2x + 1)/(x - 3).","Swap x and y: x = (2y + 1)/(y - 3).","Multiply across by (y - 3): x(y - 3) = 2y + 1.","Expand and group all y terms on one side: xy - 2y = 3x + 1.","Factor out y: y(x - 2) = 3x + 1.","Divide to isolate y: f⁻¹(x) = (3x + 1)/(x - 2)."],items_ar:["استبدال f(x) بالمتغير y: y = (2x + 1)/(x - 3).","تبديل المتغيرين x و y: x = (2y + 1)/(y - 3).","الضرب التبادلي في (y - 3): x(y - 3) = 2y + 1.","فك الأقواس وتجميع جميع حدود y في طرف واحد: xy - 2y = 3x + 1.","إخراج y كعامل مشترك: y(x - 2) = 3x + 1.","القسمة لعزل y: f⁻¹(x) = (3x + 1)/(x - 2)."],ex:"Swapping variables and collecting all y-terms on one side yields f⁻¹(x) = (3x + 1)/(x - 2).",ex_ar:"تبديل المتغيرين وتجميع حدود y في طرف واحد ينتج الدالة العكسية: f⁻¹(x) = (3x + 1)/(x - 2)."},{t:"sr",ti:"Worked Example: Find an Inverse Function",ti_ar:"مثال محلول: إيجاد الدالة العكسية",steps:["Find the inverse of \\(f(x)=3x-4\\). Replace \\(f(x)\\) with \\(y\\): \\(y=3x-4\\).","Swap \\(x\\) and \\(y\\), then solve for \\(y\\): \\(x=3y-4\\Rightarrow y=\\dfrac{x+4}{3}\\).","\\(f^{-1}(x)=\\dfrac{x+4}{3}\\)."],steps_ar:["أوجد معكوس الدالة \\(f(x)=3x-4\\). استبدل \\(f(x)\\) بـ \\(y\\): \\(y=3x-4\\).","بدّل \\(x\\) و \\(y\\)، ثم حل المعادلة بالنسبة لـ \\(y\\): \\(x=3y-4\\Rightarrow y=\\dfrac{x+4}{3}\\).","\\(f^{-1}(x)=\\dfrac{x+4}{3}\\)."]},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Functions: Composite, Inverse & Logarithmic)",q:"A student solves the equation \\(\\sqrt{2x + 25} = x - 5\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 25 = (x - 5)^2\\).","Expand the right-hand side: \\(2x + 25 = x^2 - 10x + 25\\).","Rearrange and factor: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 12\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{25} = -5\\) (\\(5 = -5\\)), which is false because the principal square root is non-negative (\\(x - 5 \\ge 0\\) requires \\(x \\ge 5\\)).","Expanding \\((x - 5)^2\\) should give \\(x^2 - 25\\) with no middle term.","Factoring \\(x^2 - 12x = 0\\) only yields \\(x = 12\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 25} = x - 5\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 5 \\ge 0 \\iff x \\ge 5\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 12\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Functions: Composite, Inverse & Logarithmic)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 25} = x - 5\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 25 = (x - 5)^2\\).","فك المربع الكامل: \\(2x + 25 = x^2 - 10x + 25\\).","الترتيب والتحليل: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 12\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(5 = -5\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 5\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 5 \\ge 0 \\implies x \\ge 5\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 12\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Functions: Composite, Inverse & Logarithmic)",q:"Let \\(f(x) = x^2 - 10x + 25\\) for \\(x \\ge 5\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 5)^2 - 25 + 25 = (x - 5)^2 + 0\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 0\\) (or \\([0, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 5)^2 + 0 \\implies (x - 5)^2 = y - 0\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 5\\)): \\(f^{-1}(x) = 5 + \\sqrt{x - 0}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 0\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 0}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 5\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Functions: Composite, Inverse & Logarithmic)",q_ar:"لتكن \\(f(x) = x^2 - 10x + 25\\) حيث \\(x \\ge 5\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(5 + \\sqrt{x - 0}\\) لأن \\(x \\ge 5\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Functions: Composite, Inverse & Logarithmic)",steps:[{l:"In \\(y = x^2 - 10x + 25\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"5",h:"Take half of 10."},{l:"Compute the minimum value \\(k = 25 - 5^2 =\\)",a:"0",h:"Subtract 25 from 25."},{l:"Evaluate \\(y\\) when \\(x = 7\\): \\(y =\\)",a:"4",h:"Compute \\((2)^2 + 0\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Functions: Composite, Inverse & Logarithmic)",steps_ar:[{l:"في الدالة \\(y = x^2 - 10x + 25\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"5",h:"اقسم معامل x وهو 10 على 2."},{l:"احسب القيمة الصغرى \\(k = 25 - 5^2 =\\)",a:"0",h:"اطرح 25 من 25."},{l:"احسب قيمة \\(y\\) عندما \\(x = 7\\):",a:"4",h:"احسب \\(4 + 0\\)."}]},{t:"qc",ti:"Quick Check: Vertex & Minimum Analysis (Functions: Composite, Inverse & Logarithmic)",ti_ar:"فحص سريع: تحليل نقطة الرأس والقيمة الصغرى (Functions: Composite, Inverse & Logarithmic)",q:"What is the minimum value of \\( f(x) = (x - 5)^2 + 7 \\) over all real \\( x \\)?",q_ar:"ما هي القيمة الصغرى للدالة \\( f(x) = (x - 5)^2 + 7 \\) لكل \\( x \\in \\mathbb{R} \\)؟",o:["\\( 7 \\)","\\( 5 \\)","\\( -5 \\)","\\( 32 \\)"],o_ar:["\\( 7 \\)","\\( 5 \\)","\\( -5 \\)","\\( 32 \\)"],a:0,ex:"Since \\( (x - 5)^2 \\ge 0 \\), the minimum value is \\( 7 \\) achieved at \\( x = 5 \\).",ex_ar:"بما أن المربع الكامل غير سالب، فإن القيمة الصغرى هي \\( 7 \\) عند \\( x = 5 \\)."}];D["est2-sequences"]=[{t:"fn",ti:"Explorer: Geometric Sequence \\(3\\cdot r^x\\)",ti_ar:"مستكشف: المتتابعة الهندسية \\(3\\cdot r^x\\)",fns:[{expr:"3*r^x",color:"#1E3A6E",label:"3·r^x"}],xrange:[0,5],yrange:[0,30],params:[{name:"r",label:"Ratio r",min:.5,max:2,step:.25,default:1.5}]},{t:"num",ti:"Numeric Entry: Sum of Infinite Geometric Series",ti_ar:"إدخال رقمي: مجموع متسلسلة هندسية لانهائية",q:"Evaluate the sum of the infinite geometric series \\(18 + 6 + 2 + \\dfrac{2}{3} + \\cdots\\).",q_ar:"احسب مجموع المتسلسلة الهندسية اللانهائية \\(18 + 6 + 2 + \\dfrac{2}{3} + \\cdots\\).",a:27,ex:"First term a₁ = 18, common ratio r = 6/18 = 1/3. Since |r| < 1, S_∞ = a₁ / (1 - r) = 18 / (1 - 1/3) = 18 / (2/3) = 27.",ex_ar:"الحد الأول a₁ = 18، والأساس المشترك r = 6/18 = 1/3. وبما أن |r| < 1، فإن S_∞ = a₁ / (1 - r) = 18 / (1 - 1/3) = 18 / (2/3) = 27."},{t:"num",ti:"Numeric Entry: Power of the Imaginary Unit",ti_ar:"إدخال رقمي: قوى الوحدة التخيلية",q:"Evaluate \\(i^{78}\\). Enter 1, -1, 0, or the integer value.",q_ar:"احسب قيمة \\(i^{78}\\). أدخل 1 أو -1 أو 0 أو القيمة العددية الصحيحة.",a:-1,ex:"78 mod 4 = 2. Since i² = -1, i⁷⁸ = (i⁴)¹⁹ · i² = (1)¹⁹ · (-1) = -1.",ex_ar:"باقي قسمة 78 على 4 هو 2. وبما أن i² = -1، فإن i⁷⁸ = (i⁴)¹⁹ · i² = (1)¹⁹ · (-1) = -1."},{t:"ord",ti:"Order the Steps: Infinite Geometric Series Evaluation",ti_ar:"رتّب الخطوات: حساب مجموع المتسلسلة الهندسية اللانهائية",prompt:"Arrange the steps to find the sum of \\(12 - 4 + \\dfrac{4}{3} - \\dfrac{4}{9} + \\cdots\\):",prompt_ar:"رتب خطوات إيجاد مجموع المتسلسلة \\(12 - 4 + \\dfrac{4}{3} - \\dfrac{4}{9} + \\cdots\\):",items:["Identify the first term: a₁ = 12.","Calculate the common ratio: r = -4 / 12 = -1/3.","Verify convergence condition: |-1/3| = 1/3 < 1, so the series converges.","Apply the sum formula: S_∞ = a₁ / (1 - r) = 12 / (1 - (-1/3)).","Simplify denominator and evaluate: 12 / (4/3) = 12 · (3/4) = 9."],items_ar:["تحديد الحد الأول: a₁ = 12.","حساب الأساس المشترك: r = -4 / 12 = -1/3.","التحقق من شرط التقارب: |-1/3| = 1/3 < 1، إذن المتسلسلة متقاربة.","تطبيق قانون المجموع اللانهائي: S_∞ = a₁ / (1 - r) = 12 / (1 - (-1/3)).","تبسيط المقام وإيجاد الناتج النهائي: 12 / (4/3) = 12 · (3/4) = 9."],ex:"Checking |r| < 1 guarantees convergence, giving S_∞ = 12 / (4/3) = 9.",ex_ar:"التحقق من أن |r| < 1 يضمن التقارب، معطياً S_∞ = 12 / (4/3) = 9."},{t:"cat",ti:"Categorize: Sequences & Complex Numbers",ti_ar:"تصنيف: المتتابعات والأعداد المركبة",categories:["Arithmetic Sequence","Geometric Series","Complex Arithmetic"],categories_ar:["متتابعة حسابية","متسلسلة هندسية","حساب الأعداد المركبة"],items:[{s:"Constant common difference d between consecutive terms",s_ar:"فرق مشترك ثابت d بين الحدود المتتالية",cat:0},{s:"Sum to infinity formula S_∞ = a₁ / (1 - r) for |r| < 1",s_ar:"قانون المجموع اللانهائي S_∞ = a₁ / (1 - r) عندما |r| < 1",cat:1},{s:"Multiplying by the conjugate (c - di) to divide fractions",s_ar:"الضرب في المرافق (c - di) لقسمة الكسور المركبة",cat:2},{s:"aₙ = a₁ + (n - 1)d",s_ar:"aₙ = a₁ + (n - 1)d",cat:0},{s:"Powers repeat in a 4-cycle: i, -1, -i, 1",s_ar:"القوى تتكرر دورياً كل 4: i, -1, -i, 1",cat:2},{s:"Ratio r between consecutive terms is constant",s_ar:"النسبة r بين الحدود المتتالية ثابتة",cat:1}],ex:"Arithmetic uses a common difference, geometric uses a common ratio, and complex numbers rely on i² = -1 and conjugates.",ex_ar:"تعتمد المتتابعة الحسابية على الفرق المشترك، والهندسية على النسبة المشتركة، والأعداد المركبة على i² = -1 والمرافق."},{t:"sr",ti:"Worked Example: Sum of a Finite Geometric Series",ti_ar:"مثال محلول: مجموع متسلسلة هندسية منتهية",steps:["Find the sum of \\(2+6+18+54+162\\). Identify \\(a=2\\), \\(r=3\\), \\(n=5\\) terms.","Use the formula \\(S_n=\\dfrac{a(r^n-1)}{r-1}\\).","Substitute: \\(S_5=\\dfrac{2(3^5-1)}{3-1}=\\dfrac{2(242)}{2}=242\\)."],steps_ar:["أوجد مجموع \\(2+6+18+54+162\\). حدد المعطيات: \\(a=2\\)، \\(r=3\\)، عدد الحدود \\(n=5\\).","استخدم قانون المجموع \\(S_n=\\dfrac{a(r^n-1)}{r-1}\\).","التعويض: \\(S_5=\\dfrac{2(3^5-1)}{3-1}=\\dfrac{2(242)}{2}=242\\)."]},{t:"qc",ti:"Quick Check: Complex Number Addition",ti_ar:"فحص سريع: جمع الأعداد المركبة",q:"Simplify \\((2+3i)+(1-i)\\)",q_ar:"بسط المقدار \\((2+3i)+(1-i)\\)",o:["\\(3+2i\\)","\\(3+4i\\)","\\(1+2i\\)","\\(3-2i\\)"],o_ar:["\\(3+2i\\)","\\(3+4i\\)","\\(1+2i\\)","\\(3-2i\\)"],a:0,ex:"Add real and imaginary parts separately: \\((2+1)+(3-1)i=3+2i\\).",ex_ar:"اجمع الجزأين الحقيقيين والتخيليين كلاً على حدة: \\((2+1)+(3-1)i=3+2i\\)."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Sequences, Series & Complex Numbers)",q:"A student solves the equation \\(\\sqrt{2x + 25} = x - 5\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 25 = (x - 5)^2\\).","Expand the right-hand side: \\(2x + 25 = x^2 - 10x + 25\\).","Rearrange and factor: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 12\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{25} = -5\\) (\\(5 = -5\\)), which is false because the principal square root is non-negative (\\(x - 5 \\ge 0\\) requires \\(x \\ge 5\\)).","Expanding \\((x - 5)^2\\) should give \\(x^2 - 25\\) with no middle term.","Factoring \\(x^2 - 12x = 0\\) only yields \\(x = 12\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 25} = x - 5\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 5 \\ge 0 \\iff x \\ge 5\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 12\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Sequences, Series & Complex Numbers)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 25} = x - 5\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 25 = (x - 5)^2\\).","فك المربع الكامل: \\(2x + 25 = x^2 - 10x + 25\\).","الترتيب والتحليل: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 12\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(5 = -5\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 5\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 5 \\ge 0 \\implies x \\ge 5\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 12\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Sequences, Series & Complex Numbers)",q:"Let \\(f(x) = x^2 - 10x + 31\\) for \\(x \\ge 5\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 5)^2 - 25 + 31 = (x - 5)^2 + 6\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 6\\) (or \\([6, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 5)^2 + 6 \\implies (x - 5)^2 = y - 6\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 5\\)): \\(f^{-1}(x) = 5 + \\sqrt{x - 6}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 6\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 6}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 5\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Sequences, Series & Complex Numbers)",q_ar:"لتكن \\(f(x) = x^2 - 10x + 31\\) حيث \\(x \\ge 5\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(5 + \\sqrt{x - 6}\\) لأن \\(x \\ge 5\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Sequences, Series & Complex Numbers)",steps:[{l:"In \\(y = x^2 - 10x + 31\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"5",h:"Take half of 10."},{l:"Compute the minimum value \\(k = 31 - 5^2 =\\)",a:"6",h:"Subtract 25 from 31."},{l:"Evaluate \\(y\\) when \\(x = 7\\): \\(y =\\)",a:"10",h:"Compute \\((2)^2 + 6\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Sequences, Series & Complex Numbers)",steps_ar:[{l:"في الدالة \\(y = x^2 - 10x + 31\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"5",h:"اقسم معامل x وهو 10 على 2."},{l:"احسب القيمة الصغرى \\(k = 31 - 5^2 =\\)",a:"6",h:"اطرح 25 من 31."},{l:"احسب قيمة \\(y\\) عندما \\(x = 7\\):",a:"10",h:"احسب \\(4 + 6\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Sequences, Series & Complex Numbers)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Sequences, Series & Complex Numbers)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["est2-geometry"]=[{t:"tf",ti:"True or False: Solid Geometry",ti_ar:"صح أم خطأ: الهندسة المجسمة (الفراغية)",items:[{s:"Volume of sphere \\(=\\frac{4}{3}\\pi r^3\\)",s_ar:"حجم الكرة \\(=\\frac{4}{3}\\pi r^3\\)",a:true,ex:"Standard formula.",ex_ar:"الصيغة القياسية لحجم الكرة."},{s:"Surface area of cube with side \\(s\\) is \\(4s^2\\)",s_ar:"المساحة الكلية لسطح مكعب طول ضلعه \\(s\\) هي \\(4s^2\\)",a:false,ex:"SA of cube \\(=6s^2\\).",ex_ar:"المساحة الكلية لسطح المكعب \\(=6s^2\\)."},{s:"Volume of cone \\(=\\frac{1}{3}\\pi r^2 h\\)",s_ar:"حجم المخروط \\(=\\frac{1}{3}\\pi r^2 h\\)",a:true,ex:"Correct.",ex_ar:"صحيح."},{s:"Volume of cylinder \\(=\\pi r^2 h\\)",s_ar:"حجم الأسطوانة \\(=\\pi r^2 h\\)",a:true,ex:"Correct.",ex_ar:"صحيح."}]},{t:"num",ti:"Numeric Entry: Regular Polygon Exterior Angle",ti_ar:"إدخال رقمي: الزاوية الخارجية للمضلع المنتظم",q:"What is the measure in degrees of one exterior angle of a regular octagon (8 sides)?",q_ar:"ما هو قياس الزاوية الخارجية بالدرجات لمضلع ثماني منتظم (8 أضلاع)؟",a:45,ex:"The exterior angle of any regular n-gon is 360° / n. For an octagon, 360° / 8 = 45°.",ex_ar:"الزاوية الخارجية لأي مضلع منتظم ذي n ضلعاً هي 360° ÷ n. وللثماني المنتظم: 360° ÷ 8 = 45°."},{t:"ord",ti:"Order the Steps: Area of an Oblique Triangle by Law of Cosines",ti_ar:"رتّب الخطوات: حساب مساحة مثلث غير قائم بصيغة هيرون",prompt:"Arrange the steps to find the area of \\(\\triangle ABC\\) given sides \\(a = 5, b = 7, c = 8\\):",prompt_ar:"رتب خطوات حساب مساحة المثلث \\(\\triangle ABC\\) الذي أطوال أضلاعه \\(a = 5, b = 7, c = 8\\):",items:["Calculate the semi-perimeter: s = (5 + 7 + 8)/2 = 10.","Apply Heron's formula: A = √[s(s - a)(s - b)(s - c)].","Substitute side lengths: A = √[10(10 - 5)(10 - 7)(10 - 8)].","Simplify under the radical: A = √[10 · 5 · 3 · 2] = √300.","Factor perfect squares: A = 10√3."],items_ar:["حساب نصف المحيط: s = (5 + 7 + 8)/2 = 10.","تطبيق صيغة هيرون: A = √[s(s - a)(s - b)(s - c)].","التعويض بأطوال الأضلاع: A = √[10(10 - 5)(10 - 7)(10 - 8)].","تبسيط ما تحت الجذر: A = √[10 · 5 · 3 · 2] = √300.","إخراج المربعات الكاملة خارج الجذر: A = 10√3."],ex:"Using Heron's formula s = 10 gives √[10(5)(3)(2)] = √300 = 10√3.",ex_ar:"استخدام صيغة هيرون عند s = 10 يعطي √[10(5)(3)(2)] = √300 = 10√3."},{t:"cat",ti:"Categorize: Triangle & Polygon Properties",ti_ar:"تصنيف: خصائص وقوانين المثلثات والمضلعات",categories:["Angles in Polygons","Right Triangle Relations","Oblique Triangle Formulas"],categories_ar:["زوايا المضلعات","علاقات المثلث القائم","قوانين المثلثات المائلة"],items:[{s:"Sum of interior angles = (n - 2) × 180°",s_ar:"مجموع الزوايا الداخلية = (n - 2) × 180°",cat:0},{s:"Exterior angles of any convex polygon sum to 360°",s_ar:"مجموع الزوايا الخارجية لأي مضلع محدب يساوي 360°",cat:0},{s:"Pythagorean theorem a² + b² = c²",s_ar:"نظرية فيثاغورس a² + b² = c²",cat:1},{s:"Law of Cosines: c² = a² + b² - 2ab cos(C)",s_ar:"قانون جيوب التمام: c² = a² + b² - 2ab cos(C)",cat:2},{s:"Heron's formula for area: √[s(s - a)(s - b)(s - c)]",s_ar:"صيغة هيرون للمساحة: √[s(s - a)(s - b)(s - c)]",cat:2},{s:"Trigonometric ratios: sin = opp/hyp, cos = adj/hyp",s_ar:"النسب المثلثية: sin = المقابل/الوتر، cos = المجاور/الوتر",cat:1}],ex:"Polygon angle sums depend on n, right triangles use Pythagorean relations, and oblique triangles use the Law of Cosines and Heron's formula.",ex_ar:"يعتمد مجموع زوايا المضلع على n، وتستخدم المثلثات القائمة علاقات فيثاغورس، وتستخدم المثلثات المائلة قانون جيوب التمام وصيغة هيرون."},{t:"sr",ti:"Worked Example: Interior Angle of a Regular Polygon",ti_ar:"مثال محلول: الزاوية الداخلية لمضلع منتظم",steps:["A regular pentagon has 5 equal interior angles. Sum of interior angles: \\((5-2)\\times180°=540°\\).","Since the pentagon is regular, divide equally: \\(\\dfrac{540°}{5}\\).","Each angle measures \\(108°\\)."],steps_ar:["المضلع الخماسي المنتظم له 5 زوايا داخلية متطابقة. مجموع الزوايا الداخلية: \\((5-2)\\times180°=540°\\).","بما أن الخماسي منتظم، نقسم المجموع بالتساوي: \\(\\dfrac{540°}{5}\\).","قياس كل زاوية هو \\(108°\\)."]},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Lines, Triangles & Polygons)",q:"A student solves the equation \\(\\sqrt{2x + 4} = x - 2\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 4 = (x - 2)^2\\).","Expand the right-hand side: \\(2x + 4 = x^2 - 4x + 4\\).","Rearrange and factor: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 6\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{4} = -2\\) (\\(2 = -2\\)), which is false because the principal square root is non-negative (\\(x - 2 \\ge 0\\) requires \\(x \\ge 2\\)).","Expanding \\((x - 2)^2\\) should give \\(x^2 - 4\\) with no middle term.","Factoring \\(x^2 - 6x = 0\\) only yields \\(x = 6\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 4} = x - 2\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 2 \\ge 0 \\iff x \\ge 2\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 6\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Lines, Triangles & Polygons)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 4} = x - 2\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 4 = (x - 2)^2\\).","فك المربع الكامل: \\(2x + 4 = x^2 - 4x + 4\\).","الترتيب والتحليل: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 6\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(2 = -2\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 2\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 2 \\ge 0 \\implies x \\ge 2\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 6\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Lines, Triangles & Polygons)",q:"Let \\(f(x) = x^2 - 4x + 10\\) for \\(x \\ge 2\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 2)^2 - 4 + 10 = (x - 2)^2 + 6\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 6\\) (or \\([6, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 2)^2 + 6 \\implies (x - 2)^2 = y - 6\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 2\\)): \\(f^{-1}(x) = 2 + \\sqrt{x - 6}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 6\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 6}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 2\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Lines, Triangles & Polygons)",q_ar:"لتكن \\(f(x) = x^2 - 4x + 10\\) حيث \\(x \\ge 2\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(2 + \\sqrt{x - 6}\\) لأن \\(x \\ge 2\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Lines, Triangles & Polygons)",steps:[{l:"In \\(y = x^2 - 4x + 10\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"2",h:"Take half of 4."},{l:"Compute the minimum value \\(k = 10 - 2^2 =\\)",a:"6",h:"Subtract 4 from 10."},{l:"Evaluate \\(y\\) when \\(x = 4\\): \\(y =\\)",a:"10",h:"Compute \\((2)^2 + 6\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Lines, Triangles & Polygons)",steps_ar:[{l:"في الدالة \\(y = x^2 - 4x + 10\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"2",h:"اقسم معامل x وهو 4 على 2."},{l:"احسب القيمة الصغرى \\(k = 10 - 2^2 =\\)",a:"6",h:"اطرح 4 من 10."},{l:"احسب قيمة \\(y\\) عندما \\(x = 4\\):",a:"10",h:"احسب \\(4 + 6\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Lines, Triangles & Polygons)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Lines, Triangles & Polygons)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["est2-trig"]=[{t:"sb",ti:"Step Builder: Solve \\(2\\sin\\theta=\\sqrt{3}\\), \\(0°\\le\\theta\\le360°\\)",ti_ar:"بناء الخطوات: حل \\(2\\sin\\theta=\\sqrt{3}\\) حيث \\(0°\\le\\theta\\le360°\\)",steps:[{l:"\\(\\sin\\theta=\\)",l_ar:"\\(\\sin\\theta=\\)",a:"sqrt(3)/2",h:"Divide both sides of \\(2\\sin\\theta = \\sqrt{3}\\) by \\(2\\).",h_ar:"اقسم طرفي المعادلة \\(2\\sin\\theta = \\sqrt{3}\\) على \\(2\\)."},{l:"Reference angle: \\(\\arcsin(\\sqrt{3}/2)=\\)",l_ar:"زاوية الإسناد: \\(\\arcsin(\\sqrt{3}/2)=\\)",a:"60",h:"Identify the acute special angle in degrees whose sine equals \\(\\frac{\\sqrt{3}}{2}\\).",h_ar:"حدد الزاوية الحادة القياسية بالدرجات التي جيبها يساوي \\(\\frac{\\sqrt{3}}{2}\\)."},{l:"2nd solution \\(=180°-60°=\\)",l_ar:"الحل الثاني \\(=180°-60°=\\)",a:"120",h:"Perform the calculation in \\(180°-60°\\) to find the result.",h_ar:"أجرِ العملية الحسابية في المقدار \\(180°-60°\\) للوصول إلى النتيجة."},{l:"Both solutions: 60° and",l_ar:"الحلان هما: 60° و",a:"120",h:"Enter the second-quadrant angle found in the previous step.",h_ar:"اكتب زاوية الربع الثاني التي حسبتها في الخطوة السابقة."}]},{t:"num",ti:"Numeric Entry: Sinusoidal Period",ti_ar:"إدخال رقمي: دورة الدالة الجيبية",q:"Find the period of the function \\(f(x) = 3\\sin(4x - \\pi) + 2\\) in terms of \\(\\pi\\). Enter the denominator \\(k\\) if the period is \\(\\pi / k\\).",q_ar:"أوجد دورة الدالة \\(f(x) = 3\\sin(4x - \\pi) + 2\\) بدلالة \\(\\pi\\). أدخل المقام \\(k\\) إذا كانت الدورة هي \\(\\pi / k\\).",a:2,ex:"For y = A sin(Bx - C) + D, Period = 2π / B. Here B = 4, so Period = 2π / 4 = π / 2. Thus k = 2.",ex_ar:"في الدالة y = A sin(Bx - C) + D، الدورة = 2π / B. هنا B = 4، إذن الدورة = 2π / 4 = π / 2. وبالتالي k = 2."},{t:"cat",ti:"Categorize: Signs of Trig Functions by Quadrant",ti_ar:"تصنيف: إشارات الدوال المثلثية حسب الأرباع",categories:["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"],categories_ar:["الربع الأول","الربع الثاني","الربع الثالث","الربع الرابع"],items:[{s:"\\sin > 0,\\; \\cos > 0",s_ar:"\\sin > 0,\\; \\cos > 0",cat:0},{s:"\\sin > 0,\\; \\cos < 0",s_ar:"\\sin > 0,\\; \\cos < 0",cat:1},{s:"\\sin < 0,\\; \\cos < 0,\\; \\tan > 0",s_ar:"\\sin < 0,\\; \\cos < 0,\\; \\tan > 0",cat:2},{s:"\\sin < 0,\\; \\cos > 0,\\; \\tan < 0",s_ar:"\\sin < 0,\\; \\cos > 0,\\; \\tan < 0",cat:3}],ex:"By the ASTC (All Students Take Calculus) rule: All positive in Q I; Sine positive in Q II; Tangent positive in Q III; Cosine positive in Q IV.",ex_ar:"وفق قاعدة الإشارات ASTC: الكل موجب في الربع الأول؛ الجيب موجب في الربع الثاني؛ الظل موجب في الربع الثالث؛ جيب التمام موجب في الربع الرابع."},{t:"ord",ti:"Order the Steps: Verifying a Trigonometric Identity",ti_ar:"رتّب الخطوات: إثبات صحة متطابقة مثلثية",prompt:"Arrange the steps to prove \\(\\dfrac{\\sin^2\\theta}{1 - \\cos\\theta} = 1 + \\cos\\theta\\):",prompt_ar:"رتب خطوات إثبات صحة المتطابقة \\(\\dfrac{\\sin^2\\theta}{1 - \\cos\\theta} = 1 + \\cos\\theta\\):",items:["Start with the left-hand side: sin²(θ) / (1 - cos(θ)).","Apply the Pythagorean identity: replace sin²(θ) with 1 - cos²(θ).","Factor the numerator as a difference of squares: (1 - cos(θ))(1 + cos(θ)).","Cancel the common nonzero factor (1 - cos(θ)) from numerator and denominator.","Conclude with the simplified right-hand side: 1 + cos(θ)."],items_ar:["البدء بالطرف الأيسر: sin²(θ) / (1 - cos(θ)).","تطبيق متطابقة فيثاغورس: استبدال sin²(θ) بـ 1 - cos²(θ).","تحليل البسط كفرق بين مربعين: (1 - cos(θ))(1 + cos(θ)).","اختصار العامل المشترك غير الصفري (1 - cos(θ)) من البسط والمقام.","الوصول إلى الطرف الأيمن المطلوب: 1 + cos(θ)."],ex:"Using sin²(θ) = 1 - cos²(θ) and factoring as a difference of squares establishes the identity algebraically.",ex_ar:"استخدام sin²(θ) = 1 - cos²(θ) والتحليل كفرق بين مربعين يثبت المتطابقة جبرياً."},{t:"sr",ti:"Worked Example: Law of Cosines",ti_ar:"مثال محلول: قانون جيوب التمام",steps:["Find side \\(c\\) with \\(a=7\\), \\(b=10\\), included angle \\(C=60°\\). Law of Cosines: \\(c^2=a^2+b^2-2ab\\cos C\\).","Substitute: \\(c^2=49+100-2(7)(10)\\cos60°=149-140(0.5)\\).","\\(c^2=149-70=79\\Rightarrow c=\\sqrt{79}\\approx8.89\\)."],steps_ar:["أوجد الضلع \\(c\\) إذا كان \\(a=7\\)، \\(b=10\\)، والزاوية المحصورة \\(C=60°\\). قانون جيوب التمام: \\(c^2=a^2+b^2-2ab\\cos C\\).","التعويض: \\(c^2=49+100-2(7)(10)\\cos60°=149-140(0.5)\\).","\\(c^2=149-70=79\\Rightarrow c=\\sqrt{79}\\approx8.89\\)."]},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Trigonometry)",q:"A student solves the equation \\(\\sqrt{2x + 4} = x - 2\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 4 = (x - 2)^2\\).","Expand the right-hand side: \\(2x + 4 = x^2 - 4x + 4\\).","Rearrange and factor: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 6\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{4} = -2\\) (\\(2 = -2\\)), which is false because the principal square root is non-negative (\\(x - 2 \\ge 0\\) requires \\(x \\ge 2\\)).","Expanding \\((x - 2)^2\\) should give \\(x^2 - 4\\) with no middle term.","Factoring \\(x^2 - 6x = 0\\) only yields \\(x = 6\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 4} = x - 2\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 2 \\ge 0 \\iff x \\ge 2\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 6\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Trigonometry)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 4} = x - 2\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 4 = (x - 2)^2\\).","فك المربع الكامل: \\(2x + 4 = x^2 - 4x + 4\\).","الترتيب والتحليل: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 6\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(2 = -2\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 2\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 2 \\ge 0 \\implies x \\ge 2\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 6\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Trigonometry)",q:"Let \\(f(x) = x^2 - 4x + 7\\) for \\(x \\ge 2\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 2)^2 - 4 + 7 = (x - 2)^2 + 3\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 3\\) (or \\([3, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 2)^2 + 3 \\implies (x - 2)^2 = y - 3\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 2\\)): \\(f^{-1}(x) = 2 + \\sqrt{x - 3}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 3\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 3}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 2\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Trigonometry)",q_ar:"لتكن \\(f(x) = x^2 - 4x + 7\\) حيث \\(x \\ge 2\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(2 + \\sqrt{x - 3}\\) لأن \\(x \\ge 2\\)."},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Trigonometry)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Trigonometry)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]},{t:"qc",ti:"Quick Check: Vertex & Minimum Analysis (Trigonometry)",ti_ar:"فحص سريع: تحليل نقطة الرأس والقيمة الصغرى (Trigonometry)",q:"What is the minimum value of \\( f(x) = (x - 8)^2 + 5 \\) over all real \\( x \\)?",q_ar:"ما هي القيمة الصغرى للدالة \\( f(x) = (x - 8)^2 + 5 \\) لكل \\( x \\in \\mathbb{R} \\)؟",o:["\\( 5 \\)","\\( 8 \\)","\\( -8 \\)","\\( 69 \\)"],o_ar:["\\( 5 \\)","\\( 8 \\)","\\( -8 \\)","\\( 69 \\)"],a:0,ex:"Since \\( (x - 8)^2 \\ge 0 \\), the minimum value is \\( 5 \\) achieved at \\( x = 8 \\).",ex_ar:"بما أن المربع الكامل غير سالب، فإن القيمة الصغرى هي \\( 5 \\) عند \\( x = 8 \\)."}];D["est2-circles"]=[{t:"fn",ti:"Explorer: Circle \\(x^2+y^2=r^2\\)",ti_ar:"مستكشف: الدائرة \\(x^2+y^2=r^2\\)",fns:[{expr:"sqrt(r^2-x^2)",color:"#1E3A6E",label:"upper"},{expr:"-sqrt(r^2-x^2)",color:"#B8801F",label:"lower"}],xrange:[-5,5],yrange:[-5,5],params:[{name:"r",label:"Radius r",min:1,max:4,step:1,default:2}]},{t:"num",ti:"Numeric Entry: Tangent Segment Length",ti_ar:"إدخال رقمي: طول قطعة المماس",q:"A point \\(P\\) is located 13 units from the center of a circle with radius 5. What is the length of the tangent segment from \\(P\\) to the point of tangency on the circle?",q_ar:"تقع النقطة \\(P\\) على بعد 13 وحدة من مركز دائرة نصف قطرها 5. ما هو طول قطعة المماس المرسومة من \\(P\\) إلى نقطة التماس على الدائرة؟",a:12,ex:"The radius to the point of tangency forms a right triangle with hypotenuse 13 and leg 5. By the Pythagorean theorem: tangent length = √(13² - 5²) = √(169 - 25) = √144 = 12.",ex_ar:"نصف القطر الواصل إلى نقطة التماس يعامد المماس، مكوّناً مثلثاً قائماً وتره 13 وضلعه 5. بنظرية فيثاغورس: طول المماس = √(13² - 5²) = √(169 - 25) = √144 = 12."},{t:"cat",ti:"Categorize: Conic Sections from Standard Equations",ti_ar:"تصنيف: القطوع المخروطية من معادلاتها القياسية",categories:["Circle","Ellipse","Hyperbola","Parabola"],categories_ar:["دائرة","قطع ناقص","قطع زائد","قطع مكافئ"],items:[{s:"\\((x - 2)^2 + (y + 3)^2 = 16\\)",s_ar:"\\((x - 2)^2 + (y + 3)^2 = 16\\)",cat:0},{s:"\\(\\dfrac{(x - 1)^2}{25} + \\dfrac{(y + 2)^2}{9} = 1\\)",s_ar:"\\(\\dfrac{(x - 1)^2}{25} + \\dfrac{(y + 2)^2}{9} = 1\\)",cat:1},{s:"\\(\\dfrac{(x + 4)^2}{16} - \\dfrac{(y - 1)^2}{9} = 1\\)",s_ar:"\\(\\dfrac{(x + 4)^2}{16} - \\dfrac{(y - 1)^2}{9} = 1\\)",cat:2},{s:"\\((y - 3)^2 = 8(x + 1)\\)",s_ar:"\\((y - 3)^2 = 8(x + 1)\\)",cat:3}],ex:"Equal coefficients on squared terms indicate a circle; unequal positive coefficients indicate an ellipse; opposite signs indicate a hyperbola; only one squared variable indicates a parabola.",ex_ar:"المعاملات المتساوية للحدود المربعة تدل على دائرة؛ والمعاملات الموجبة المختلفة تدل على قطع ناقص؛ والإشارات المتعاكسة تدل على قطع زائد؛ ووجود متغير تربيعي واحد فقط يدل على قطع مكافئ."},{t:"ord",ti:"Order the Steps: Completing the Square for Circle Equation",ti_ar:"رتّب الخطوات: إكمال المربع لمعادلة الدائرة",prompt:"Arrange the steps to find the center and radius of \\(x^2 + y^2 - 6x + 8y = 0\\):",prompt_ar:"رتب خطوات إيجاد مركز ونصف قطر الدائرة \\(x^2 + y^2 - 6x + 8y = 0\\):",items:["Rearrange terms grouping variables: (x² - 6x) + (y² + 8y) = 0.","Complete the square for x: add (-6/2)² = 9 to both sides.","Complete the square for y: add (8/2)² = 16 to both sides.","Write in factored form: (x - 3)² + (y + 4)² = 25.","Identify center (h, k) = (3, -4) and radius r = √25 = 5."],items_ar:["إعادة ترتيب وتجميع الحدود المتشابهة: (x² - 6x) + (y² + 8y) = 0.","إكمال المربع لـ x: إضافة (-6/2)² = 9 إلى كلا الطرفين.","إكمال المربع لـ y: إضافة (8/2)² = 16 إلى كلا الطرفين.","الكتابة في صورة مربعات كاملة: (x - 3)² + (y + 4)² = 25.","تحديد المركز (h, k) = (3, -4) ونصف القطر r = √25 = 5."],ex:"Completing the square on both x and y puts the equation into standard form (x - h)² + (y - k)² = r².",ex_ar:"إكمال المربع لـ x و y يحول المعادلة إلى الصورة القياسية للدائرة (x - h)² + (y - k)² = r²."},{t:"sr",ti:"Worked Example: Equation of a Circle",ti_ar:"مثال محلول: معادلة الدائرة",steps:["Write the equation of a circle with center \\((-1,2)\\) and radius 5. Standard form: \\((x-h)^2+(y-k)^2=r^2\\).","Substitute \\(h=-1\\), \\(k=2\\), \\(r=5\\): \\((x-(-1))^2+(y-2)^2=5^2\\).","Simplify: \\((x+1)^2+(y-2)^2=25\\)."],steps_ar:["اكتب معادلة الدائرة التي مركزها \\((-1,2)\\) ونصف قطرها 5. الصيغة القياسية: \\((x-h)^2+(y-k)^2=r^2\\).","التعويض بـ \\(h=-1\\)، \\(k=2\\)، \\(r=5\\): \\((x-(-1))^2+(y-2)^2=5^2\\).","التبسيط: \\((x+1)^2+(y-2)^2=25\\)."]},{t:"qc",ti:"Quick Check: Circle Center",ti_ar:"فحص سريع: مركز الدائرة",q:"The center of \\((x-3)^2+(y+4)^2=16\\) is:",q_ar:"مركز الدائرة \\((x-3)^2+(y+4)^2=16\\) هو:",o:["\\((3,-4)\\)","\\((-3,4)\\)","\\((3,4)\\)","\\((-3,-4)\\)"],o_ar:["\\((3,-4)\\)","\\((-3,4)\\)","\\((3,4)\\)","\\((-3,-4)\\)"],a:0,ex:"Standard form \\((x-h)^2+(y-k)^2=r^2\\) has center \\((h,k)=(3,-4)\\).",ex_ar:"الصيغة القياسية \\((x-h)^2+(y-k)^2=r^2\\) مركزها \\((h,k)=(3,-4)\\)."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Circles & Conic Sections)",q:"A student solves the equation \\(\\sqrt{2x + 4} = x - 2\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 4 = (x - 2)^2\\).","Expand the right-hand side: \\(2x + 4 = x^2 - 4x + 4\\).","Rearrange and factor: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 6\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{4} = -2\\) (\\(2 = -2\\)), which is false because the principal square root is non-negative (\\(x - 2 \\ge 0\\) requires \\(x \\ge 2\\)).","Expanding \\((x - 2)^2\\) should give \\(x^2 - 4\\) with no middle term.","Factoring \\(x^2 - 6x = 0\\) only yields \\(x = 6\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 4} = x - 2\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 2 \\ge 0 \\iff x \\ge 2\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 6\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Circles & Conic Sections)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 4} = x - 2\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 4 = (x - 2)^2\\).","فك المربع الكامل: \\(2x + 4 = x^2 - 4x + 4\\).","الترتيب والتحليل: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 6\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(2 = -2\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 2\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 2 \\ge 0 \\implies x \\ge 2\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 6\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Circles & Conic Sections)",q:"Let \\(f(x) = x^2 - 4x + 11\\) for \\(x \\ge 2\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 2)^2 - 4 + 11 = (x - 2)^2 + 7\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 7\\) (or \\([7, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 2)^2 + 7 \\implies (x - 2)^2 = y - 7\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 2\\)): \\(f^{-1}(x) = 2 + \\sqrt{x - 7}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 7\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 7}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 2\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Circles & Conic Sections)",q_ar:"لتكن \\(f(x) = x^2 - 4x + 11\\) حيث \\(x \\ge 2\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(2 + \\sqrt{x - 7}\\) لأن \\(x \\ge 2\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Circles & Conic Sections)",steps:[{l:"In \\(y = x^2 - 4x + 11\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"2",h:"Take half of 4."},{l:"Compute the minimum value \\(k = 11 - 2^2 =\\)",a:"7",h:"Subtract 4 from 11."},{l:"Evaluate \\(y\\) when \\(x = 4\\): \\(y =\\)",a:"11",h:"Compute \\((2)^2 + 7\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Circles & Conic Sections)",steps_ar:[{l:"في الدالة \\(y = x^2 - 4x + 11\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"2",h:"اقسم معامل x وهو 4 على 2."},{l:"احسب القيمة الصغرى \\(k = 11 - 2^2 =\\)",a:"7",h:"اطرح 4 من 11."},{l:"احسب قيمة \\(y\\) عندما \\(x = 4\\):",a:"11",h:"احسب \\(4 + 7\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Circles & Conic Sections)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Circles & Conic Sections)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["est2-solids"]=[{t:"num",ti:"Numeric Entry: Sphere Volume Scaling",ti_ar:"إدخال رقمي: معامل تمدد حجم الكرة",q:"If the radius of a sphere is multiplied by 3, by what factor is its volume multiplied?",q_ar:"إذا ضُرب نصف قطر كرة في 3، فما المعامل الذي يتضاعف به حجمها؟",a:27,ex:"Volume scales as the cube of the linear dimension: 3³ = 27.",ex_ar:"يتناسب الحجم مع مكعب البعد الخطي: 3³ = 27."},{t:"ord",ti:"Order the Steps: Volume of a Frustum of a Cone",ti_ar:"رتّب الخطوات: حجم المخروط الناقص",prompt:"Arrange the steps to find the volume of a cone frustum with lower radius R, upper radius r, and height h:",prompt_ar:"رتب خطوات حساب حجم مخروط ناقص نصف قطر قاعدته الكبرى R، وقاعدته الصغرى r، وارتفاعه h:",items:["Complete the full cone by extending sides to find apex height H using similar triangles: H / (H - h) = R / r.","Calculate the volume of the entire large cone: V_large = (1/3)π R² H.","Calculate the volume of the removed top cone: V_small = (1/3)π r² (H - h).","Subtract top cone from large cone: V_frustum = V_large - V_small.","Verify with standard frustum formula: V = (1/3)π h (R² + Rr + r²)."],items_ar:["إكمال المخروط الأكبر بمد الراسم لإيجاد الارتفاع الكلي H بتشابه المثلثات: H / (H - h) = R / r.","حساب حجم المخروط الأكبر كاملاً: V_large = (1/3)π R² H.","حساب حجم المخروط الأصغر المقتطع في الأعلى: V_small = (1/3)π r² (H - h).","طرح حجم المخروط الأصغر من المخروط الأكبر: V_frustum = V_large - V_small.","التحقق باستخدام صيغة المخروط الناقص القياسية: V = (1/3)π h (R² + Rr + r²)."],ex:"The volume of a frustum is found by subtracting the removed cone from the larger cone, resulting in (1/3)π h (R² + Rr + r²).",ex_ar:"يُحسب حجم المخروط الناقص بطرح المخروط الصغير المقتطع من المخروط الكبير، وينتج (1/3)π h (R² + Rr + r²)."},{t:"cat",ti:"Categorize: 3D Solid Geometric Formulas",ti_ar:"تصنيف: قوانين المجسمات ثلاثية الأبعاد",categories:["Volume Formulas","Surface Area Formulas"],categories_ar:["قوانين الحجوم","قوانين المساحات السطحية"],items:[{s:"Sphere: V = (4/3)π r³",s_ar:"الكرة: V = (4/3)π r³",cat:0},{s:"Cone: V = (1/3)π r² h",s_ar:"المخروط: V = (1/3)π r² h",cat:0},{s:"Cylinder: V = π r² h",s_ar:"الأسطوانة: V = π r² h",cat:0},{s:"Sphere: A = 4π r²",s_ar:"الكرة: A = 4π r²",cat:1},{s:"Cylinder (total): A = 2π r² + 2π r h",s_ar:"الأسطوانة (الكلية): A = 2π r² + 2π r h",cat:1},{s:"Cone (lateral): A = π r l",s_ar:"المخروط (الجانبية): A = π r l",cat:1}],ex:"Volumes involve 3D cubic dimensional relationships, while surface areas involve 2D square units.",ex_ar:"تتعامل الحجوم مع أبعاد تكعيبية ثلاثية، بينما تتعامل المساحات السطحية مع وحدات مربعة ثنائية الأبعاد."},{t:"sr",ti:"Worked Example: Volume of a Cone",ti_ar:"مثال محلول: حجم المخروط",steps:["Find the volume of a cone with radius 3 and height 8. Formula: \\(V=\\dfrac13\\pi r^2h\\).","Substitute \\(r=3\\), \\(h=8\\): \\(V=\\dfrac13\\pi(9)(8)\\).","\\(V=24\\pi\\)."],steps_ar:["أوجد حجم مخروط نصف قطر قاعدته 3 وارتفاعه 8. القانون: \\(V=\\dfrac13\\pi r^2h\\).","التعويض: \\(r=3\\)، \\(h=8\\): \\(V=\\dfrac13\\pi(9)(8)\\).","\\(V=24\\pi\\)."]},{t:"qc",ti:"Quick Check: Similar Solids",ti_ar:"فحص سريع: المجسمات المتشابهة",q:"If two similar solids have a scale factor of 2, their volumes scale by:",q_ar:"إذا كان معامل مقياس التشابه بين مجسمين يساوي 2، فإن حجميهما يتناسبان بمعامل:",o:["8","2","4","16"],o_ar:["8","2","4","16"],a:0,ex:"Volume scales by the cube of the linear scale factor: \\(2^3=8\\).",ex_ar:"يتناسب الحجم مع مكعب معامل المقياس الخطي: \\(2^3=8\\)."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Solid Geometry & Similarity)",q:"A student solves the equation \\(\\sqrt{2x + 25} = x - 5\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 25 = (x - 5)^2\\).","Expand the right-hand side: \\(2x + 25 = x^2 - 10x + 25\\).","Rearrange and factor: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 12\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{25} = -5\\) (\\(5 = -5\\)), which is false because the principal square root is non-negative (\\(x - 5 \\ge 0\\) requires \\(x \\ge 5\\)).","Expanding \\((x - 5)^2\\) should give \\(x^2 - 25\\) with no middle term.","Factoring \\(x^2 - 12x = 0\\) only yields \\(x = 12\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 25} = x - 5\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 5 \\ge 0 \\iff x \\ge 5\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 12\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Solid Geometry & Similarity)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 25} = x - 5\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 25 = (x - 5)^2\\).","فك المربع الكامل: \\(2x + 25 = x^2 - 10x + 25\\).","الترتيب والتحليل: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 12\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(5 = -5\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 5\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 5 \\ge 0 \\implies x \\ge 5\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 12\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Solid Geometry & Similarity)",q:"Let \\(f(x) = x^2 - 10x + 28\\) for \\(x \\ge 5\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 5)^2 - 25 + 28 = (x - 5)^2 + 3\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 3\\) (or \\([3, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 5)^2 + 3 \\implies (x - 5)^2 = y - 3\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 5\\)): \\(f^{-1}(x) = 5 + \\sqrt{x - 3}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 3\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 3}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 5\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Solid Geometry & Similarity)",q_ar:"لتكن \\(f(x) = x^2 - 10x + 28\\) حيث \\(x \\ge 5\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(5 + \\sqrt{x - 3}\\) لأن \\(x \\ge 5\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Solid Geometry & Similarity)",steps:[{l:"In \\(y = x^2 - 10x + 28\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"5",h:"Take half of 10."},{l:"Compute the minimum value \\(k = 28 - 5^2 =\\)",a:"3",h:"Subtract 25 from 28."},{l:"Evaluate \\(y\\) when \\(x = 7\\): \\(y =\\)",a:"7",h:"Compute \\((2)^2 + 3\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Solid Geometry & Similarity)",steps_ar:[{l:"في الدالة \\(y = x^2 - 10x + 28\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"5",h:"اقسم معامل x وهو 10 على 2."},{l:"احسب القيمة الصغرى \\(k = 28 - 5^2 =\\)",a:"3",h:"اطرح 25 من 28."},{l:"احسب قيمة \\(y\\) عندما \\(x = 7\\):",a:"7",h:"احسب \\(4 + 3\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Solid Geometry & Similarity)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Solid Geometry & Similarity)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["est2-stats"]=[{t:"num",ti:"Numeric Entry: Permutations of Distinct Roles",ti_ar:"إدخال رقمي: التباديل لمناصب متمايزة",q:"In how many ways can a president, vice president, and treasurer be chosen from a club of 10 members?",q_ar:"بكم طريقة يمكن اختيار رئيس ونائب رئيس وأمين صندوق من بين 10 أعضاء في نادٍ؟",a:720,ex:"Since distinct offices represent ordered positions, use permutations: ₁₀P₃ = 10 × 9 × 8 = 720.",ex_ar:"بما أن المناصب المختلفة تمثل مواقع محددة الترتيب، نستخدم التباديل: ₁₀P₃ = 10 × 9 × 8 = 720."},{t:"cat",ti:"Categorize: Counting Principle Selection",ti_ar:"تصنيف: اختيار مبدأ العد المناسب",categories:["Permutations (Order Matters)","Combinations (Order Does Not Matter)"],categories_ar:["تباديل (الترتيب مهم)","توافيق (الترتيب غير مهم)"],items:[{s:"Assigning 1st, 2nd, and 3rd place medals in a race",s_ar:"توزيع ميداليات المراكز الأول والثاني والثالث في سباق",cat:0},{s:"Selecting a 4-digit PIN code without repetition",s_ar:"اختيار رمز سري (PIN) من 4 أرقام دون تكرار",cat:0},{s:"Choosing 5 players to start a basketball game",s_ar:"اختيار 5 لاعبين لبدء مباراة كرة سلة",cat:1},{s:"Selecting a committee of 3 from a class of 20",s_ar:"اختيار لجنة من 3 طلاب من فصل به 20 طالباً",cat:1},{s:"Dealing a 5-card poker hand from a standard deck",s_ar:"توزيع يد من 5 بطاقات من أوراق اللعب",cat:1}],ex:"Permutations are used when order or role distinction is significant; combinations are used when subsets are unordered.",ex_ar:"تُستخدم التباديل عندما يكون الترتيب أو تحديد المناصب ذا أهمية؛ وتُستخدم التوافيق عند اختيار مجموعات دون ترتيب."},{t:"ord",ti:"Order the Steps: At Least One Probability with Complement Rule",ti_ar:"رتّب الخطوات: احتمال وقوع حدث على الأقل باستخدام قاعدة المتممة",prompt:"Arrange the steps to find the probability of getting at least one head in 4 fair coin flips:",prompt_ar:"رتب خطوات حساب احتمال الحصول على صورة واحدة على الأقل عند رمي قطعة نقود عادلة 4 مرات:",items:["Identify the total number of coin flips: n = 4.","Identify the complement event: getting zero heads (all tails).","Calculate the probability of the complement: P(all tails) = (1/2)⁴ = 1/16.","Apply the complement rule: P(at least 1 head) = 1 - P(all tails).","Evaluate: 1 - 1/16 = 15/16."],items_ar:["تحديد العدد الإجمالي لإلقاءات قطعة النقود: n = 4.","تحديد الحدث المتمم: عدم ظهور أي صورة (الحصول على كتابة في جميع الرميات).","حساب احتمال الحدث المتمم: P(كلها كتابة) = (1/2)⁴ = 1/16.","تطبيق قاعدة الحدث المتمم: P(صورة واحدة على الأقل) = 1 - P(كلها كتابة).","الحساب: 1 - 1/16 = 15/16."],ex:"Using P(at least 1) = 1 - P(none) simplifies multi-step binomial probability computations.",ex_ar:"استخدام P(واحد على الأقل) = 1 - P(لا شيء) يبسط حسابات الاحتمال ذي الحدين."},{t:"sr",ti:"Worked Example: Combinations",ti_ar:"مثال محلول: التوافيق",steps:["How many ways can you choose 3 books from a shelf of 8 different books? Since order doesn't matter, use combinations: \\(\\binom{n}{r}=\\dfrac{n!}{r!(n-r)!}\\).","Substitute \\(n=8\\), \\(r=3\\): \\(\\binom83=\\dfrac{8!}{3!5!}\\).","Compute: \\(\\dfrac{8\\times7\\times6}{3\\times2\\times1}=56\\)."],steps_ar:["بكم طريقة يمكنك اختيار 3 كتب من رف يحتوي على 8 كتب مختلفة؟ بما أن الترتيب غير مهم، نستخدم التوافيق: \\(\\binom{n}{r}=\\dfrac{n!}{r!(n-r)!}\\).","التعويض: \\(n=8\\)، \\(r=3\\): \\(\\binom83=\\dfrac{8!}{3!5!}\\).","الحساب: \\(\\dfrac{8\\times7\\times6}{3\\times2\\times1}=56\\)."]},{t:"qc",ti:"Quick Check: Factorials",ti_ar:"فحص سريع: مضروب العدد",q:"\\(5!\\) equals:",q_ar:"قيمة \\(5!\\) تساوي:",o:["120","20","25","60"],o_ar:["120","20","25","60"],a:0,ex:"\\(5\\times4\\times3\\times2\\times1=120\\).",ex_ar:"\\(5\\times4\\times3\\times2\\times1=120\\)."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Statistics & Probability)",q:"A student solves the equation \\(\\sqrt{2x + 16} = x - 4\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 16 = (x - 4)^2\\).","Expand the right-hand side: \\(2x + 16 = x^2 - 8x + 16\\).","Rearrange and factor: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 10\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{16} = -4\\) (\\(4 = -4\\)), which is false because the principal square root is non-negative (\\(x - 4 \\ge 0\\) requires \\(x \\ge 4\\)).","Expanding \\((x - 4)^2\\) should give \\(x^2 - 16\\) with no middle term.","Factoring \\(x^2 - 10x = 0\\) only yields \\(x = 10\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 16} = x - 4\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 4 \\ge 0 \\iff x \\ge 4\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 10\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Statistics & Probability)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 16} = x - 4\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 16 = (x - 4)^2\\).","فك المربع الكامل: \\(2x + 16 = x^2 - 8x + 16\\).","الترتيب والتحليل: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 10\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(4 = -4\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 4\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 4 \\ge 0 \\implies x \\ge 4\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 10\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Statistics & Probability)",q:"Let \\(f(x) = x^2 - 8x + 15\\) for \\(x \\ge 4\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 4)^2 - 16 + 15 = (x - 4)^2 + -1\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge -1\\) (or \\([-1, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 4)^2 + -1 \\implies (x - 4)^2 = y - -1\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 4\\)): \\(f^{-1}(x) = 4 + \\sqrt{x - -1}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge -1\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - -1}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 4\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Statistics & Probability)",q_ar:"لتكن \\(f(x) = x^2 - 8x + 15\\) حيث \\(x \\ge 4\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(4 + \\sqrt{x - -1}\\) لأن \\(x \\ge 4\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Statistics & Probability)",steps:[{l:"In \\(y = x^2 - 8x + 15\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"4",h:"Take half of 8."},{l:"Compute the minimum value \\(k = 15 - 4^2 =\\)",a:"-1",h:"Subtract 16 from 15."},{l:"Evaluate \\(y\\) when \\(x = 6\\): \\(y =\\)",a:"3",h:"Compute (2)^2 + -1."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Statistics & Probability)",steps_ar:[{l:"في الدالة \\(y = x^2 - 8x + 15\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"4",h:"اقسم معامل x وهو 8 على 2."},{l:"احسب القيمة الصغرى \\(k = 15 - 4^2 =\\)",a:"-1",h:"اطرح 16 من 15."},{l:"احسب قيمة \\(y\\) عندما \\(x = 6\\):",a:"3",h:"احسب 4 + -1."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Statistics & Probability)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Statistics & Probability)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}]});